    pub fn build(&self) -> Result<::api::Request> {
        let mut query_pairs = Vec::new();

        if let Some(archived) = self.internal.archived {
            query_pairs.push(("archived", archived.to_string()));
        }

        if let Some(visibility) = self.internal.visibility {
            query_pairs.push(("visibility", visibility.to_string()));
        }

        if let Some(order_by) = self.internal.order_by {
            query_pairs.push(("order_by", order_by.to_string()));
        }

        if let Some(sort) = self.internal.sort {
            query_pairs.push(("sort", sort.to_string()));
        }

        if let Some(ref search) = self.internal.search {
            query_pairs.push(("search", search.clone()));
        }

        let query_string = serde_urlencoded::to_string(&query_pairs)
            .map_err(|e| Error::from(e))?;

        let url = format!("projects/all?{}", query_string);

        Ok(::api::Request::new(&url, ::api::Method::Get, None))
    }

