impl AroundMiddleware for Middleware {
    fn around(&self, req: &mut Request, res: Response) -> Result<Response, Box<dyn Error + Send + Sync>> {
        let mut response = self.dist.handle(req, res)?;
        if response.status().is_success() {
            return Ok(response);
        }

        // If the request is for a non-existent file, try to serve index.html
        // This is useful for single-page apps where client-side routing is used
        if response.status().is_client_error() {
            let mut index_req = req.clone();
            index_req.set_path("/index.html");
            let index_response = self.dist.handle(&mut index_req, Response::new())?;
            if index_response.status().is_success() {
                return Ok(index_response);
            }
        }

        Ok(response)
    }
}

