/// Encrypt a message using ChaCha20 and authenticate it with HMAC-SHA512
    pub fn encrypt(&self, message: &[u8]) -> (Vec<u8>, [u8; AUTH_TAG_BYTES]) {
        // Encrypt the message using ChaCha20
        let mut encrypted = message.to_vec();
        chacha20::stream_xor(&mut encrypted, &self.nonce, &self.encryption_key);

        // Generate authentication tag for the encrypted message
        let auth_tag = self.plain_auth_tag(&encrypted);

        (encrypted, auth_tag)
    }

    /// Decrypt a message using ChaCha20 and verify its authenticity with HMAC-SHA512
    pub fn decrypt(&self, encrypted_message: &[u8], auth_tag: &[u8]) -> Option<Vec<u8>> {
        // Verify the authentication tag before decryption
        if !self.verify_auth(auth_tag, encrypted_message) {
            return None;
        }

        // Decrypt the message using ChaCha20
        let mut decrypted = encrypted_message.to_vec();
        chacha20::stream_xor(&mut decrypted, &self.nonce, &self.encryption_key);

        Some(decrypted)
    }

