    fn execute_task(task: &mut Task, scene: &Arc<Scene>, img_tx: &mut Sender<Image>) {
        // Execute the task, which may involve tracing rays, gathering samples, and tonemapping.
        match task {
            Task::Trace(ray, x, y, width, height, samples) => {
                let mut trace_unit = TraceUnit::new(scene.clone(), *x, *y, *width, *height, *samples);
                let result = trace_unit.trace(ray);
                let mut gather_unit = GatherUnit::new(*x, *y, *width, *height, *samples, result);
                gather_unit.gather();
                let mut plot_unit = PlotUnit::new(*x, *y, *width, *height, *samples);
                let mut tonemap_unit = TonemapUnit::new(*x, *y, *width, *height, *samples);
                let image = tonemap_unit.tonemap(plot_unit.plot());
                // Send the image segment back to the main thread.
                if let Err(_) = img_tx.send(image) {
                    // If the receiver has been dropped, there's no point in continuing.
                    return;
