            model = model * Matrix4::from_scale(0.2);  // it's a bit too big for our scene, so scale it down
            shader.useProgram();
            shader.setMat4(c_str!("projection"), &projection);
            shader.setMat4(c_str!("view"), &view);
            shader.setMat4(c_str!("model"), &model);

            // draw model as usual
