    pub fn find<P, Q, C>(&self, path: P, checker: C) -> Result<PathBuf, Error>
    where
        P: AsRef<Path>,
        Q: AsRef<Path>,
        C: Checker,
    {
        let path = path.as_ref();
        let mut current_path = path.to_path_buf();

        if !current_path.is_absolute() {
            let cwd = env::current_dir().map_err(|e| Error::Io(e))?;
            current_path = current_path.to_absolute(cwd);
        }

        if checker.is_valid(&current_path) {
            return Ok(current_path);
        }

        let mut current = current_path.clone();
        while let Some(parent) = current.parent() {
            current = parent.to_path_buf();
            if checker.is_valid(&current) {
                return Ok(current);
            }
        }

        Err(Error::NotFound(path.to_path_buf()))
    }
}

