impl<'a> Iterator for &'a TreeWalker {
    type Item = DomRoot<Node>;

    fn next(&mut self) -> Option<DomRoot<Node>> {
        match self.NextNode() {
            Ok(node) => node,
            Err(_) =>
            // The Err path happens only when a JavaScript
