// Listen starts the server listening on the configured address.
func (s *Server) Listen() error {
	listener, err := net.Listen("tcp", s.Addr)
	if err != nil {
		return err
	}
	s.listeners = append(s.listeners, listener)
	return nil
}

// ListenAndServe starts the server listening and serving requests.
func (s *Server) ListenAndServe() error {
	if err := s.Listen(); err != nil {
		return err
	}
	return s.Serve()
}

// Serve accepts incoming connections and serves them.
func (s *Server) Serve() error {
	for _, listener := range s.listeners {
		go func(l net.Listener) {
			for {
				conn, err := l.Accept()
				if err != nil {
					// Ignore errors from closed listeners
					if netErr, ok := err.(net.Error); ok && netErr.Temporary() {
						continue
					}
