	elapsed := time.Since(startTime)
	ph.timermetrics.Record(elapsed)

	if *statusEvery > 0 && (atomic.AddUint64(&ph.counter, 1)%uint64(*statusEvery)) == 0 {
		log.Printf("processed %d messages", ph.counter)
	}

	return nil
}

