	case ModeRoundRobin:
		addr := ph.addresses[atomic.AddUint64(&ph.counter, 1)%uint64(len(ph.addresses))]
		ph.Publish(addr, m.Body)
	case ModeHostPool:
		addr, err := ph.hostPool.Get()
		if err != nil {
