func (r *Reader) NextFile() (*zip.File, error) {
	if len(r.unread) > 0 {
		file := r.unread[len(r.unread)-1]
		r.unread = r.unread[:len(r.unread)-1]
		return file, nil
	}
	if r.rc != nil {
		return nil, io.EOF
	}
	// If no unread files, read the next file from the archive.
	file, err := r.Reader.Next()
	if err != nil {
		return nil, err
	}
	if file == nil {
		return nil, io.EOF
	}
	r.unread = append(r.unread, file)
	return file, nil
}

