func (kr *KRun) loadMeshEnv(ctx context.Context) error {
	if kr.Cfg == nil {
		return nil // no k8s, skip loading.
	}
	d, err := kr.Cfg.GetCM(ctx, "istio-system", "mesh-env")
	if err != nil {
