// Render returns the rendered bootstrap configuration as JSON.
func (c *BootstrapConfig) Render() ([]byte, error) {
	// Resolve any environment variables in the config values.
	if err := c.resolveEnvVars(); err != nil {
		return nil, err
	}

	// Parse the template.
	tmpl, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return nil, fmt.Errorf("failed to parse bootstrap template: %w", err)
	}

	// Execute the template.
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, c); err != nil {
		return nil, fmt.Errorf("failed to render bootstrap template: %w", err)
	}

	// Marshal the result to ensure it's valid JSON.
	var result interface{}
	if err := json.Unmarshal(buf.Bytes(), &result); err != nil {
		return nil, fmt.Errorf("rendered bootstrap is not valid JSON: %w", err)
	}

	// Re-marshal with indentation for readability.
	return json.MarshalIndent(result, "", "  ")
}

