// packABI packs the given values according to the ABI specification.
func packABI(types []Type, values []interface{}) ([]byte, error) {
	var buf []byte
	for i, typ := range types {
		value := values[i]
		packed, err := packType(typ, value)
		if err != nil {
			return nil, err
		}
		buf = append(buf, packed...)
	}
	return buf, nil
}

// packType packs a single value according to its type.
func packType(typ Type, value interface{}) ([]byte, error) {
	switch typ.Kind {
	case Uint:
		if v, ok := value.(*big.Int); ok {
			return packUint(v, typ.Size), nil
		}
		if v, ok := value.(uint); ok {
			return packUint(big.NewInt(int64(v)), typ.Size), nil
		}
		if v, ok := value.(int); ok {
			return packUint(big.NewInt(int64(v)), typ.Size), nil
		}
