func get(sz int) []float64 {
	poolMu.RLock()
	b, ok := pool[sz]
	poolMu.RUnlock()
	if ok {
		b.buf = b.buf[:sz]
		return b.buf
	}

	return make([]float64, sz)
}

// put returns a buffer to the pool.
func put(buf []float64) {
	if len(buf) == 0 {
		return
	}

	poolMu.Lock()
	defer poolMu.Unlock()
	p, ok := pool[len(buf)]
	if !ok {
		p = &poolBuf{buf: make([]float64, len(buf)), sz: len(buf)}
		pool[len(buf)] = p
	}
	p.buf = buf
}

