		if url.User == outURL.User && url.User != nil {
			t.Errorf("urls %v, %v share reference to same UserInfo %v", url, outURL, url.User)
		}
		if urlHasPassword(outURL) {
			t.Errorf("output url %v contains unredacted password", outURL)
		}
	}
