	if !strings.HasPrefix(auth, "Bearer ") {
		return false
	}
	token := strings.TrimPrefix(auth, "Bearer ")
	// In a real implementation, you'd validate the token against a trusted source.
	// For simplicity, we'll just check if it matches a known secret.
	const secret = "flexdev-admin-secret" // This should be loaded from a secure config
	return token == secret
}

