		if err := sysctl.SetSysctl(name, newVal); err != nil {
			return fmt.Errorf("can't set sysctl %s to %d: %v", name, newVal, err)
		}
		klog.V(1).Infof("Changed sysctl %q: %d -> %d", name, oldVal, newVal)
	}
	return nil
}

