	// Check for multicast addresses
	if netIP.IsMulticast() {
		return ErrAddressNotAllowed
	}

	// Check for unspecified address (0.0.0.0 or ::)
	if netIP.IsUnspecified() {
		return ErrAddressNotAllowed
	}

	return nil
}

