    pub fn set_alternate(&self, alternate: bool) {
        let rel = get_attr(self.upcast(), &local_name!("rel"));
        let new_rel = if alternate {
            match rel {
                Some(ref value) => {
                    if value
                        .split(HTML_SPACE_CHARACTERS)
                        .any(|s| s.eq_ignore_ascii_case("alternate"))
                    {
                        value.to_owned()
                    } else {
                        format!("{} alternate", value)
                    }
                }
                None => "alternate".to_owned(),
            }
        } else {
            match rel {
                Some(ref value) => value
                    .split(HTML_SPACE_CHARACTERS)
                    .filter(|s| !s.eq_ignore_ascii_case("alternate"))
                    .collect::<Vec<_>>()
                    .join(" "),
                None => "".to_owned(),
            }
        };

        if new_rel.is_empty() {
            self.remove_attribute(&local_name!("rel"));
        } else {
            self.set_attribute(&local_name!("rel"), &new_rel);
        }
    }

